//! A speed test: generated bytes, as many as the client asks for up to a cap, for a
//! throughput measurement worth the name rather than a few megabytes that mostly time latency.

use std::sync::Arc;

use axum::body::{Body, Bytes};
use axum::extract::{Query, State};
use axum::http::{StatusCode, header};
use axum::response::{IntoResponse, Response};
use axum::routing::get;
use axum::{Router, middleware};
use serde::Deserialize;
use sqlx::SqlitePool;

use super::ApiError;
use super::auth::{AppState, require_user};

const MIB: u64 = 1024 * 1024;
const DEFAULT_BYTES: u64 = 25 * MIB;
const MAX_BYTES: u64 = 200 * MIB;
const CHUNK: usize = 64 * 1024;
/// Tests running at once; more would measure each other.
const AT_ONCE: usize = 2;

/// The speed test route, for everyone signed in.
pub fn routes(pool: SqlitePool) -> Router {
    let auth = AppState {
        pool,
        limiter: Arc::default(),
    };
    Router::new()
        .route("/api/v1/speedtest", get(speedtest))
        .route_layer(middleware::from_fn_with_state(auth, require_user))
        .with_state(Arc::new(tokio::sync::Semaphore::new(AT_ONCE)))
}

#[derive(Deserialize)]
struct SpeedQuery {
    bytes: Option<u64>,
}

/// Streams `bytes` pseudo-random bytes (25 MiB by default, 200 MiB at most): random, so no
/// proxy on the way can compress them and flatter the result. Never cached.
async fn speedtest(
    State(running): State<Arc<tokio::sync::Semaphore>>,
    Query(query): Query<SpeedQuery>,
) -> Result<Response, ApiError> {
    let bytes = query.bytes.unwrap_or(DEFAULT_BYTES);
    if !(1..=MAX_BYTES).contains(&bytes) {
        return Err(ApiError::new(
            StatusCode::BAD_REQUEST,
            format!("bytes is 1 to {MAX_BYTES} (200 MiB)"),
        ));
    }
    let Ok(permit) = running.try_acquire_owned() else {
        return Err(ApiError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "two speed tests are running already; try again shortly",
        ));
    };
    let mut seed = [0u8; 8];
    getrandom::fill(&mut seed).map_err(|e| anyhow::anyhow!("no randomness available: {e}"))?;
    // xorshift64*: fast, and random enough that nothing compresses it. Never zero.
    let state = u64::from_le_bytes(seed) | 1;
    let stream = futures_util::stream::unfold(
        (state, bytes, permit),
        |(mut state, left, permit)| async move {
            if left == 0 {
                return None;
            }
            let len = usize::try_from(left).map_or(CHUNK, |left| left.min(CHUNK));
            let mut chunk = Vec::with_capacity(len + 8);
            while chunk.len() < len {
                state ^= state >> 12;
                state ^= state << 25;
                state ^= state >> 27;
                chunk.extend_from_slice(&state.wrapping_mul(0x2545_F491_4F6C_DD1D).to_le_bytes());
            }
            chunk.truncate(len);
            let left = left - len as u64;
            Some((
                Ok::<_, std::convert::Infallible>(Bytes::from(chunk)),
                (state, left, permit),
            ))
        },
    );
    Ok((
        [
            (header::CONTENT_TYPE, "application/octet-stream".to_owned()),
            (header::CONTENT_LENGTH, bytes.to_string()),
            (header::CACHE_CONTROL, "no-store".to_owned()),
        ],
        Body::from_stream(stream),
    )
        .into_response())
}

#[cfg(test)]
mod tests {
    use axum::http::Request;
    use http_body_util::BodyExt;
    use tower::ServiceExt;

    use super::*;
    use crate::auth::{self, TokenKind};
    use crate::db;

    async fn app() -> (Router, String) {
        let pool = db::open_in_memory().await;
        let user = auth::create_user(&pool, "viewer", "viewer-password".into(), false)
            .await
            .unwrap()
            .unwrap();
        let (_, token) = auth::issue_token(&pool, user.id, TokenKind::Session, "test")
            .await
            .unwrap();
        (routes(pool), token)
    }

    async fn get(app: &Router, uri: &str, token: Option<&str>) -> Response {
        let mut request = Request::get(uri);
        if let Some(token) = token {
            request = request.header(header::AUTHORIZATION, format!("Bearer {token}"));
        }
        app.clone()
            .oneshot(request.body(Body::empty()).unwrap())
            .await
            .unwrap()
    }

    #[tokio::test]
    async fn streams_as_many_random_bytes_as_asked() {
        let (app, token) = app().await;
        let response = get(&app, "/api/v1/speedtest?bytes=200000", Some(&token)).await;
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(response.headers()[header::CONTENT_LENGTH], "200000");
        assert_eq!(response.headers()[header::CACHE_CONTROL], "no-store");
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(body.len(), 200_000);
        // Random: every byte value turns up, about as often as any other.
        let mut counts = [0usize; 256];
        for b in &body {
            counts[usize::from(*b)] += 1;
        }
        assert!(
            counts.iter().all(|&c| (500..1100).contains(&c)),
            "{counts:?}"
        );
        let other = get(&app, "/api/v1/speedtest?bytes=200000", Some(&token)).await;
        let other = other.into_body().collect().await.unwrap().to_bytes();
        assert_ne!(body, other, "a fresh seed each time");

        let response = get(&app, "/api/v1/speedtest", Some(&token)).await;
        assert_eq!(
            response.headers()[header::CONTENT_LENGTH],
            (25 * MIB).to_string()
        );
    }

    #[tokio::test]
    async fn sizes_are_capped_and_a_user_is_needed() {
        let (app, token) = app().await;
        for bad in ["0", "209715201", "-1", "lots"] {
            let response = get(
                &app,
                &format!("/api/v1/speedtest?bytes={bad}"),
                Some(&token),
            )
            .await;
            assert_eq!(response.status(), StatusCode::BAD_REQUEST, "{bad}");
        }
        let response = get(&app, "/api/v1/speedtest?bytes=209715200", Some(&token)).await;
        assert_eq!(response.status(), StatusCode::OK, "200 MiB is allowed");
        drop(response);
        assert_eq!(
            get(&app, "/api/v1/speedtest", None).await.status(),
            StatusCode::UNAUTHORIZED
        );
    }

    #[tokio::test]
    async fn two_run_at_once() {
        let (app, token) = app().await;
        let first = get(&app, "/api/v1/speedtest", Some(&token)).await;
        let second = get(&app, "/api/v1/speedtest", Some(&token)).await;
        let third = get(&app, "/api/v1/speedtest", Some(&token)).await;
        assert_eq!(third.status(), StatusCode::SERVICE_UNAVAILABLE);
        // Read to the end, a test makes way for the next.
        first.into_body().collect().await.unwrap();
        assert_eq!(
            get(&app, "/api/v1/speedtest?bytes=1", Some(&token))
                .await
                .status(),
            StatusCode::OK
        );
        drop(second);
    }
}
